-- Equivalencias iniciales auditables. WatchPower queda en estado pending hasta
-- validar una muestra real de la cuenta; no se presentan campos adivinados.
on conflict(provider,original_name,canonical_name,normalizer_version) do update set original_unit=excluded.original_unit,normalized_unit=excluded.normalized_unit,scale=excluded.scale,formula=excluded.formula,sign_convention=excluded.sign_convention,update_frequency_seconds=excluded.update_frequency_seconds,confidence=excluded.confidence,observations=excluded.observations;
